/* Player ratings of both sides after the final whistle, as a broadcast shows them: the engine's own marks (matchRatings:
   goals, assists, saves, clean sheet, cards, result), home side first like the board above, the best player starred. */
/* With the final score: who scored (minute, assist, penalty or own goal) and who was booked or sent off, each side under
   its own half of the board. */
function BmatchFactsHTML(M){const side=id=>{const goals=M.ev.filter(e=>(e.t==='goal'||e.t==='pen'||e.t==='own')&&e.team===id).map(e=>`<li><span aria-hidden="true">⚽</span><span><strong>${esc(e.name||'')}</strong> <bdi>${e.m}′</bdi>${e.t==='pen'?' · פנדל':e.t==='own'?' · שער עצמי':''}${e.asstName?`<small>בישול: ${esc(e.asstName)}</small>`:''}</span></li>`);
    const cards=M.ev.filter(e=>(e.t==='yellow'||e.t==='red')&&e.team===id).map(e=>`<li><span aria-hidden="true">${e.t==='red'?'🟥':'🟨'}</span><span>${esc(e.name||'')} <bdi>${e.m}′</bdi><small>${e.t==='red'?'כרטיס אדום':'כרטיס צהוב'}</small></span></li>`);
    return `<ul>${goals.join('')}${cards.join('')||''}${goals.length||cards.length?'':'<li class="bmuted"><span></span><span>ללא שערים וכרטיסים</span></li>'}</ul>`};
  return `<section class="bfacts" aria-label="כובשים, מבשלים וכרטיסים">${side(M.h)}${side(M.a)}</section>`}
function BratingsHTML(M){try{if(!M.ratings)matchRatings(M,club(M.h),club(M.a))}catch(e){return ''}
  const order={GK:0,DF:1,MF:2,FW:3};const side=id=>{const c=club(id);return Object.entries(M.ps?.[id]||{}).filter(([,s])=>s.r!=null).map(([pid,s])=>({p:c.players.find(p=>p.id===+pid),s})).filter(x=>x.p).sort((x,y)=>(order[x.p.pos]-order[y.p.pos])||(y.s.min-x.s.min))};
  const hs=side(M.h),as=side(M.a);if(!hs.length&&!as.length)return '';let star=null;for(const x of [...hs,...as])if(!star||x.s.r>star.s.r)star=x;
  const col=(c,rows)=>`<div><h4><i style="background:${esc(c.c1)}"></i>${esc(c.name)}</h4><ol>${rows.map(x=>{const s=x.s,marks=[s.g?'⚽'+(s.g>1?s.g:''):'',s.a?'🅰'+(s.a>1?s.a:''):'',x.p.pos==='GK'&&s.sv?'🧤'+s.sv:'',s.red?'🟥':s.y?'🟨':''].filter(Boolean).join(' ');return `<li class="${x===star?'bstar':''}" title="${esc(fullName(x.p))}"><b class="brate ${s.r>=8?'top':s.r>=7?'good':s.r>=6?'ok':'low'}">${s.r.toFixed(1)}</b><span>${esc(x.p.last||x.p.first)}${x===star?' ⭐':''}</span>${marks?`<small>${marks}</small>`:''}</li>`}).join('')}</ol></div>`;
  return `<section class="bratings" aria-label="ציוני שחקנים"><h3>ציוני שחקנים</h3>${star?`<p class="bratings-star">⭐ שחקן המשחק: <strong>${esc(fullName(star.p))}</strong> <bdi>${star.s.r.toFixed(1)}</bdi></p>`:''}<div class="bratings-cols">${col(club(M.h),hs)}${col(club(M.a),as)}</div></section>`}
function BfinishRound(liveMatch){const b=Bstate();if(!b.schedule[b.round]||(liveMatch&&liveMatch.bRound!==b.round))return;document.querySelector('.bdialog')?.remove();const rounds=b.schedule.length,c=me();let mine;for(const [hid,aid] of b.schedule[b.round]){const h=club(hid),a=club(aid);BensureXI(me());const M=liveMatch&&liveMatch.h===hid&&liveMatch.a===aid?liveMatch:createMatch(h,a,{kind:'friendly',neutral:false});while(!M.done)stepMinute(M);BrecordStats(M);h.P++;a.P++;h.GF+=M.gh;h.GA+=M.ga;a.GF+=M.ga;a.GA+=M.gh;if(M.gh===M.ga){h.D++;a.D++;h.pts++;a.pts++}else{const win=M.gh>M.ga?h:a,lose=win===h?a:h;win.W++;win.pts+=3;lose.L++}if(hid===G.me||aid===G.me){mine=M;if(hid===G.me){const demand=Math.round((c.baseDemand||c.cap*.75)*(1+Math.min(.15,c.W*.01)));const crowd=Math.min(c.cap,demand);Bledger('הכנסה מכרטיסים · '+crowd.toLocaleString('he')+' אוהדים',crowd*80)}}}const installment=(total)=>Math.round(total*(b.round+1)/rounds)-Math.round(total*b.round/rounds);Bledger('שכר שחקנים',-installment(Bsum()));Bledger('תפעול האצטדיון',-installment(Boperating()));if(c.sponsor)Bledger('תשלום חסות',installment(c.sponsor.annual));for(const p of c.players)if(p.pos===b.focus){p.bTraining=(p.bTraining||0)+1;if(p.bTraining%8===0)p.ovr=Math.min(p.pot||99,p.ovr+1)}if(b.build&&!--b.build.left){c.cap=b.build.cap;b.build=null}b.round++;G.wk=b.round;b.last=mine?{h:mine.h,a:mine.a,gh:mine.gh,ga:mine.ga}:null;if(mine)BboardAfter(mine);Btab='home';if(BcareerRound()==='fired')Bleave('fired');else{Bwrite();Brender()}if(mine)Bdialog(`<div class="bresult"><span class="beyebrow">תוצאת המשחק</span><h2 class="bresult-board"><span>${kitSVG(club(mine.h),'lg')}<strong>${esc(club(mine.h).name)}</strong></span>${scoreSides(mine.gh,mine.ga,{label:club(mine.h).name+' '+mine.gh+', '+club(mine.a).name+' '+mine.ga})}<span>${kitSVG(club(mine.a),'lg')}<strong>${esc(club(mine.a).name)}</strong></span></h2>${BmatchFactsHTML(mine)}${BratingsHTML(mine)}<p class="bmuted">התנועות הכספיות של המחזור עודכנו. אפשר לראות אותן בכסף וחסויות.</p><div class="bresult-foot">${Bbutton('ממשיכים','data-bclose')}</div></div>`)}
function Bupgrade(){const n=Blevels.find(l=>l.cap>me().cap);if(!n||Bstate().build)return;const left=me().money-n.cost;Bdialog(`<h2>משדרגים ל־${n.cap.toLocaleString('he')} מקומות?</h2><p>עלות עכשיו: ${Bmoney(n.cost)}</p><p>יישאר בחשבון: ${Bmoney(left)}</p><p>תפעול חדש לשנה: ${Bmoney(n.cap*12)} · העבודה תסתיים בעוד 3 מחזורים.</p>${left>=Bcommitment()+(n.cap-me().cap)*12*Bremaining()?Bbutton('אישור תחילת הבנייה','data-action="build"'):'<p class="bnegative">כדאי לחכות: אין מספיק כסף לשדרוג ולהוצאות שנותרו בעונה.</p>'}`)}
function Bsummary(){const b=Bstate(),ls=b.ledger.filter(x=>x.season===b.season),income=ls.filter(x=>x.amount>0).reduce((s,x)=>s+x.amount,0),expenses=-ls.filter(x=>x.amount<0).reduce((s,x)=>s+x.amount,0);Bdialog(`<span class="beyebrow">עונה ${b.season}</span><h2>מה למדנו מהמספרים?</h2><p>הכנסות: ${Bmoney(income)}</p><p>הוצאות: ${Bmoney(expenses)}</p><p>רווח או הפסד: ${Bmoney(income-expenses)}</p><div class="blearn">${income>=expenses?'שמרת על הכנסות גבוהות מההוצאות. לפני רכש חדש, כדאי לשמור רזרבה.':'ההוצאות היו גבוהות מההכנסות. בעונה הבאה כדאי להשוות את שכר הסגל להכנסות לפני רכישה.'}</div>${(v=>`<div class="bverdict"><h3>${v.stay?'ההנהלה':'סוף הדרך במועדון'}</h3><p>${v.text}</p></div>${v.stay?Bbutton(v.renew?'חותם לעונות נוספות':'לעונה הבאה','data-action="newseason"'):Bbutton('להצעות שעל השולחן','data-action="released"')}${v.stay&&v.offers.length?`<div class="boffers"><h3>הצעות ממועדונים אחרים</h3>${v.offers.map(o=>BofferHTML(o,'data-bjob')).join('')}</div>`:''}`)(BseasonVerdict())}`)}
function Btips(){const b=G?.beginner;return !b||b.tips===true||(b.tips!==false&&b.round<2&&b.season<=1)}
function Brender(){document.body.classList.add('beginner');document.body.classList.toggle('btips-off',!Btips());document.body.dataset.btab=Btab;if(G?.beginner?.live){BbroadcastView();return}if(G?.beginner?.out){document.getElementById('top')?.classList.add('hide');document.getElementById('nav')?.classList.add('hide');document.getElementById('main').innerHTML=BoutHTML();return}document.getElementById('top')?.classList.add('hide');document.getElementById('nav')?.classList.add('hide');const main=document.getElementById('main');if(!G?.beginner&&Bstart.step!=='name'){main.innerHTML=`<div class="bpick-page"><div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header>${BstartHTML()}<p role="status">${esc(Bnotice)}</p></div></div>`;return}
if(!G?.beginner){main.innerHTML=`<div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header><section class="bopening"><video autoplay muted loop playsinline poster="assets/intro-poster.jpg" aria-hidden="true"><source src="assets/intro.webm" type="video/webm"><source src="assets/intro.mp4" type="video/mp4"></video><div class="bopening-copy"><span class="bpill">הכדורגל שלך מתחיל כאן</span><h1>האורות נדלקים.<br>המועדון מחכה לך.</h1><p>חתום על חוזה. בנה סגל. הובל את המועדון לניצחון.</p>${Bbutton('מתחילים קריירה ←','data-bchoose')}<span class="bopening-note">שחקנים אמיתיים · משחקים חיים · החלטות שלך</span></div></section>${BstartHTML()}${pcupEntryHTML('b')}${Rooms.intro()}<p role="status">${esc(Bnotice)}</p></div>`;return}const c=me();main.innerHTML=`<div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><div class="bclubname">${kitSVG(c,'sm')}<strong>${esc(c.name)}</strong></div><span class="bpill">מצב מתחילים</span></header><nav class="bnav" aria-label="תפריט ראשי">${BNAV.map(([id,t,icon])=>`<button data-tab="${id}" class="${id===Btab?'active':''}" ${id===Btab?'aria-current="page"':''}>${Bicon(icon)}<span>${t}</span></button>`).join('')}</nav><main class="bcontent">${({home:Bhome,squad:Bsquad,league:Bleague,market:Bmarket,training:Btraining,finance:Bfinance,stadium:Bstadium}[Btab]||Bhome)()}</main><footer class="bfooter"><span role="status">${esc(Bnotice)}</span><button type="button" class="bbtn secondary" data-bsave>שמור שוב</button><span>GOALASSO START · לומדים דרך המשחק</span><button type="button" class="blink" data-action="tips">${Btips()?'להסתיר טיפים':'להציג טיפים'}</button>${buildStampHTML()}</footer></div>`}
