document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-bchoose')){$('bstart')?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('bcoach')?.focus({preventScroll:true});return}if(BstartClick(el))return;if(el.hasAttribute('data-bsave')){Bwrite();Brender();return}if(el.hasAttribute('data-bclose')){el.closest('dialog')?.remove();return}if(el.dataset.start){Bcreate(el.dataset.start);return}if(!G?.beginner)return;try{const stored=JSON.parse(localStorage.getItem(BK)||'null');if(stored&&stored.rev!==BsaveRev){Bnotice='הקריירה עודכנה בחלון אחר. רענן את העמוד לפני המשך.';Brender();return}}catch(err){}if(el.dataset.tab){Btab=el.dataset.tab;Brender();window.scrollTo?.(0,0)}if(el.dataset.category){Bcategory=el.dataset.category;Brender()}if(el.dataset.player)Bdetail(+el.dataset.player);if(el.dataset.focus){Bstate().focus=el.dataset.focus;Bwrite();Brender()}if(el.dataset.sponsorB&&!me().sponsor){const offer=Bstate().sponsorOffers.find(x=>x.id===el.dataset.sponsorB),brand=SPONSOR_CATALOG.find(x=>x.id===offer?.id);if(brand){me().sponsor={name:brand.name,brandId:brand.id,annual:offer.annual,years:1};Bwrite();Brender()}}if(el.dataset.sign)Bsign(+el.dataset.sign,+el.dataset.fee,el.dataset.loan==='1');if(el.hasAttribute('data-lineup-slot'))BchooseLineup(+el.dataset.lineupSlot);if(el.dataset.lineupIn)BsetLineup(+el.dataset.lineupIn);if(el.dataset.sell)BsaleDialog(+el.dataset.sell);const a=el.dataset.action;if(a==='sell-confirm')BconfirmSale();if(a==='edit-lineup'){el.closest('dialog')?.remove();Btab='squad';Brender()}if(a==='auto'){me().lineup=autoLineupFor(me());Bwrite();Brender()}if(a==='offer')Boffer();if(a==='loan')Boffer(true);if(a==='counter'&&Bcounter){document.getElementById('boffer').value=Bcounter;document.getElementById('bfirstcost').innerHTML=Bmoney(Bcounter+Byear(Bfind(Bselected).p))}if(a==='signed'){el.closest('dialog')?.remove();Btab='squad';Brender()}if(el.dataset.bjob){const b=Bstate(),o=[b.offer,...((b.out&&b.out.offers)||[]),...((b.verdict&&b.verdict.offers)||[])].find(x=>x&&x.key===el.dataset.bjob);if(o){el.closest('dialog')?.remove();BtakeJob(o)}return}if(a==='resign'){Bdialog(`<span class="beyebrow">התפטרות</span><h2>לעזוב את ${esc(me().name)}?</h2><p>העונה במועדון הזה תסתיים עבורך, ותבחר מועדון חדש מבין ההצעות שיגיעו. אי אפשר לבטל.</p>${Bbutton('כן, אני מתפטר','data-action="resign-yes"')}<button type="button" class="blink" data-bclose>נשאר במועדון</button>`);return}if(a==='resign-yes'){el.closest('dialog')?.remove();Bleave('resigned');return}if(a==='released'){el.closest('dialog')?.remove();Bleave('fired');return}if(a==='decline'){Bstate().offer=null;Bwrite();Brender();return}if(a==='tips'){const b=Bstate();b.tips=!Btips();Bwrite();Brender();return}if(a==='prematch')Bprematch();if(a==='play')Bplay();if(a==='upgrade')Bupgrade();if(a==='build'){const n=Blevels.find(l=>l.cap>me().cap);if(n&&!Bstate().build&&me().money-n.cost>=Bcommitment()+(n.cap-me().cap)*12*Bremaining()){Bledger('הרחבת האצטדיון',-n.cost);Bstate().build={cap:n.cap,left:3};Bwrite();el.closest('dialog')?.remove();Brender()}}if(a==='season')Bsummary();if(a==='newseason'&&Bstate().round>=Bstate().schedule.length){const b=Bstate();for(const l of b.loans){const p=me().players.find(p=>p.id===l.pid);if(p){me().players=me().players.filter(x=>x.id!==p.id);club(l.club).players.push(p)}}b.loans=[];BstayOn();b.season++;G.season=b.season;me().sponsor=null;b.sponsorOffers=pickSponsorBrands(me(),3).map(x=>({id:x.id,annual:Math.round(Math.max(Bsum()*.4,300000)),years:1}));Bseason();Bwrite();el.closest('dialog')?.remove();Brender()}});
/* Beginner club management and season statistics. */
let BlineupSlot=null;
function BensureStats(){const b=Bstate();if(!b.playerStats){b.playerStats={};b.recordedMatches={};b.statsStartRound=b.round||0}b.recordedMatches=b.recordedMatches||{}}
function Bstandings(){return Bstate().league.map(id=>club(id)).filter(Boolean).sort((a,b)=>b.pts-a.pts||(b.GF-b.GA)-(a.GF-a.GA)||b.GF-a.GF||a.name.localeCompare(b.name,'he'))}
function BrecordStats(M){BensureStats();const b=Bstate(),key=[b.season,b.round,M.h,M.a].join(':');if(b.recordedMatches[key])return;const add=(pid,cid,field)=>{const p=club(cid)?.players.find(p=>p.id===pid);if(!p)return;const s=b.playerStats[pid]||(b.playerStats[pid]={pid,name:fullName(p),clubId:cid,goals:0,assists:0});s.clubId=cid;s[field]++};for(const e of M.ev){if(e.t==='goal'||e.t==='pen'){add(e.pid,e.team,'goals');if(e.t==='goal'&&e.asst)add(e.asst,e.team,'assists')}}b.recordedMatches[key]=true}
function Bleaders(field){BensureStats();return Object.values(Bstate().playerStats).filter(s=>s[field]>0).sort((a,b)=>b[field]-a[field]||b.goals-a.goals||a.name.localeCompare(b.name,'he'))}
function Bleague(){BensureStats();const b=Bstate();const leaderboard=(field,title)=>`<section class="bpanel"><h2>${title}</h2><div class="bleaders">${Bleaders(field).map((s,i)=>{const f=Bfind(s.pid);return `<button class="bleader" data-player="${s.pid}"><b>${i+1}</b>${f?Bportrait(f.p,f.c):''}<span><strong>${esc(s.name)}</strong><small>${esc(club(s.clubId)?.name||'')}</small></span><b class="bleader-count">${s[field]}</b></button>`}).join('')||'<p>עדיין אין נתונים. הטבלה תתעדכן אחרי המשחקים.</p>'}</div></section>`;return `${Bheader('כל הליגה במקום אחד','טבלאות הליגה',`עונה ${b.season} · הושלמו ${b.round} מתוך ${b.schedule.length} מחזורים`)}<section class="bpanel"><h2>טבלת הליגה</h2><div class="btable-wrap"><table class="bleague-table"><thead><tr><th>#</th><th>קבוצה</th><th>מש׳</th><th>נצ׳</th><th>תיקו</th><th>הפ׳</th><th>שערים</th><th>הפרש</th><th>נק׳</th></tr></thead><tbody>${Bstandings().map((c,i)=>`<tr class="${c.id===G.me?'bmyclub':''}"><td>${i+1}</td><th>${esc(c.name)}${c.id===G.me?' ★':''}</th><td>${c.P}</td><td>${c.W}</td><td>${c.D}</td><td>${c.L}</td><td><bdi>${c.GF}:${c.GA}</bdi></td><td><bdi>${c.GF-c.GA}</bdi></td><td><strong>${c.pts}</strong></td></tr>`).join('')}</tbody></table></div><p class="bmuted">הדירוג נקבע לפי נקודות, הפרש שערים ואז שערי זכות. אפשר לגלול את הטבלה לצדדים.</p></section>${b.statsStartRound>0?`<p class="blearn">בשמירה הזאת נתוני הכובשים והמבַשלים נאספים ממחזור ${b.statsStartRound+1}. תוצאות המחזורים הקודמים נשמרו בטבלת הליגה, אך פירוט הכובשים לא נשמר בגרסה הישנה.</p>`:''}<div class="btwocol">${leaderboard('goals','מלך השערים')}${leaderboard('assists','מלך הבישולים')}</div>`}
function BensureXI(c=me()){ensureLineup(c);const used=new Set(),slots=slotsFor(c.formation),av=available(c);c.lineup=slots.map((slot,i)=>{let p=av.find(p=>p.id===c.lineup[i]&&!used.has(p.id)&&(slot!=='GK'||p.pos==='GK'));if(!p)p=av.filter(p=>!used.has(p.id)&&(slot!=='GK'||p.pos==='GK')).sort((a,b)=>((b.pos===slot?100:0)+b.ovr)-((a.pos===slot?100:0)+a.ovr))[0];if(p)used.add(p.id);return p?.id??null});return c.lineup}
function Bsquad(){const c=me();BensureXI(c);const slots=slotsFor(c.formation),pos=Bstandings().findIndex(x=>x.id===c.id)+1;return `${Bheader('המועדון שלי',esc(c.name),`${esc(c.country)} · ${esc(c.stadium)} · מקום ${pos} בליגה`)}<div class="btoolbar">${Bbutton('טבלת הליגה','data-tab="league"','secondary')}${Bbutton('בחר הרכב מומלץ','data-action="auto"','secondary')}</div><div class="bclub-summary"><span>${c.players.length} שחקנים</span><span>${c.pts} נקודות</span><span>${c.W} ניצחונות</span><span>שווי סגל ${Bmoney(c.players.reduce((n,p)=>n+Bvalue(p),0))}</span></div><section class="bpanel"><div class="btoolbar"><h2>ההרכב שלי</h2><label>מערך <select id="bformation">${Object.keys(FORMATIONS).map(f=>`<option ${c.formation===f?'selected':''}>${f}</option>`).join('')}</select></label></div><p>לחץ על שחקן במגרש כדי להחליף אותו בשחקן מהספסל. השינויים נשמרים למשחק הבא.</p><div class="bformation formation-board" style="--club-color:${esc(c.c1)};--club-ink:${inkFor(c.c1)}"><div class="formation-grass">${pitchLines()}</div>${slots.map((slot,i)=>{const l=slotLayout(c.formation)[i],x=50+(l.x-50)*(.80+l.y*.002),y=18+l.y*.72;const p=c.players.find(p=>p.id===c.lineup[i]);return `<button class="bformation-player" style="left:${x}%;top:${y}%" data-lineup-slot="${i}" aria-label="${esc(p?fullName(p):'עמדה פנויה')}">${p?formationPortraitHTML(c,p,'beginner'+i):'<span>＋</span>'}<strong>${esc(p?p.last||p.first:'עמדה פנויה')}</strong><small>${POSHE[slot]}${p?' · '+p.ovr:''}</small></button>`}).join('')}</div></section><h2>כל הסגל · ${c.players.length} שחקנים</h2><p class="bmuted">בפרטי שחקן אפשר לראות את הנתונים שלו ולהציע אותו למכירה.</p><div class="bplayers">${c.players.map(p=>Bplayer(p,c)).join('')}</div>`}
function BchooseLineup(slot){if(Bstate().live)return;BensureXI();if(!Number.isInteger(slot)||slot<0||slot>=11)return;BlineupSlot=slot;const c=me(),position=slotsFor(c.formation)[slot],out=c.players.find(p=>p.id===c.lineup[slot]);const candidates=available(c).filter(p=>!c.lineup.includes(p.id)&&(position!=='GK'||p.pos==='GK')).sort((a,b)=>((b.pos===position?100:0)+b.ovr)-((a.pos===position?100:0)+a.ovr));Bdialog(`<h2>שינוי בהרכב · ${POSHE[position]}</h2><p>${out?esc(fullName(out))+' יֵרד לספסל.':'בחר שחקן לעמדה הפנויה.'}</p>${out?Bbutton('פרטי '+fullName(out),`data-player="${out.id}"`,'secondary'):''}<h3>מי ייכנס להרכב?</h3><div class="bsub-list">${candidates.map(p=>`<button class="bsub-player" data-lineup-in="${p.id}">${Bportrait(p,c)}<span><strong>${esc(fullName(p))}</strong><small>${POSHE[p.pos]} · דירוג ${p.ovr}${slotPenalty(p,position)>0?' · לא בעמדה הטבעית':''}</small></span></button>`).join('')||'<p>אין שחקן זמין מתאים בספסל.</p>'}</div>`)}
function BsetLineup(pid){if(Bstate().live||BlineupSlot===null)return false;const c=me(),p=available(c).find(p=>p.id===pid),slot=slotsFor(c.formation)[BlineupSlot];if(!p||!slot||c.lineup.includes(pid)||(slot==='GK'&&p.pos!=='GK'))return false;const lineup=c.lineup.slice();lineup[BlineupSlot]=pid;if(c.country==='ישראל'&&lineup.filter(id=>c.players.find(p=>p.id===id)?.foreign).length>MAX_FOREIGN_XI){Bdialog('<h2>מגבלת זרים</h2><p>ניתן לשלב עד שישה זרים בהרכב.</p>');return false}c.lineup=lineup;BlineupSlot=null;Bwrite();document.querySelector('.bdialog')?.remove();Btab='squad';Brender();return true}
function BsaleBlocked(p){if(Bstate().live)return 'אפשר למכור שחקנים בין המשחקים.';if(Bstate().loans.some(l=>l.pid===p.id))return 'השחקן מושאל למועדון שלך ואינו בבעלותך.';if(me().players.length<=14)return 'צריך להשאיר לפחות 14 שחקנים בסגל.';if(p.pos==='GK'&&me().players.filter(p=>p.pos==='GK').length<=2)return 'צריך להשאיר לפחות שני שוערים בסגל.';return ''}
function BsaleDialog(pid){const p=me().players.find(p=>p.id===pid);if(!p)return;const blocked=BsaleBlocked(p);if(blocked){Bdialog(`<h2>מכירת שחקן</h2><p>${blocked}</p>`);return}const fee=Math.max(50000,Math.round(Bvalue(p)*.9/50000)*50000);const buyer=G.clubs.filter(c=>c.id!==G.me&&c.players.length<35&&c.money>=fee&&c.money-fee>=Byear(p)*Bremaining()).sort((a,b)=>Math.abs(strength(a)-p.ovr)-Math.abs(strength(b)-p.ovr))[0];if(!buyer){Bdialog('<h2>אין כרגע הצעה מתאימה</h2><p>לא נמצא מועדון עם תקציב ומקום בסגל. נסה שוב בהמשך העונה.</p>');return}Bstate().saleOffer={pid,buyer:buyer.id,fee};Bwrite();Bdialog(`<div class="bprofile">${Bportrait(p,me())}<h2>הצעה עבור ${esc(fullName(p))}</h2></div><p>${esc(buyer.name)} מציעה לרכוש את השחקן.</p><div class="btransaction"><span>שווי שוק</span>${Bmoney(Bvalue(p))}</div><div class="btransaction"><span>דמי ההעברה שתקבל</span>${Bmoney(fee)}</div><div class="btransaction"><span>שכר שנתי שייחסך</span>${Bmoney(Byear(p))}</div><div class="blearn">אחרי המכירה יהיו בחשבון ${Bmoney(me().money+fee)}. השחקן יעבור למועדון הרוכש ויֵצא מההרכב שלך.</div>${Bbutton('אישור מכירת השחקן','data-action="sell-confirm"')}`)}
function BconfirmSale(){const o=Bstate().saleOffer;if(!o)return false;const c=me(),p=c.players.find(p=>p.id===o.pid),buyer=club(o.buyer);if(!p||BsaleBlocked(p)||!buyer||buyer.id===c.id||buyer.players.length>=35||buyer.money<o.fee||!Number.isFinite(o.fee)||o.fee<0)return false;buyer.money-=o.fee;c.players=c.players.filter(x=>x.id!==p.id);buyer.players.push(p);Bledger('מכירת '+fullName(p)+' ל'+buyer.name,o.fee);c.lineup=(c.lineup||[]).map(id=>id===p.id?null:id);BensureXI(c);ensureCaptain(c);delete Bstate().saleOffer;Bwrite();Btab='squad';Brender();Bdialog(`<h2>המכירה הושלמה</h2><p>${esc(fullName(p))} עבר ל${esc(buyer.name)} תמורת ${Bmoney(o.fee)}.</p>${Bbutton('בחזרה לסגל','data-bclose')}`);return true}

/* ====================== beginner career: leagues, contract, board, offers ======================
   Leagues the coach can work in (Bcat): Israel's four (top, Leumit, Liga Alef north and south) and the foreign leagues the
   data has real squads for. A club is addressed by a stable key (c.bkey): the id of an Israeli top club, 'eu<n>' (EURO_CLUBS),
   'l:<id>' (Leumit), 'a:<name>' (Liga Alef), 'w:<league>:<name>' (a market-league club). Only the clubs of a league somebody
   works in are built (BensureLeague), so the save stays small.
   The coach: b.coach, b.contract {years, wage (per month, for the story only), goal = worst acceptable place}, b.board 0..100.
   Results move the board; a board that lost its patience dismisses him (b.out), he may resign, and clubs make offers before a
   season (any league) and during it (same league only, so the table he joins is the one being played). */
function Bcat(){if(Bcat.c)return Bcat.c;const base=Bdefs().map(d=>Object.assign({},d,{str:d.key.startsWith('eu')?EURO_CLUBS[+d.key.slice(2)][6]:(LSTR[d.key]||60)}));const il=base.filter(d=>d.country==='ישראל'),eu=base.filter(d=>d.country!=='ישראל');
  const W=(k,withCountry)=>{const L=WORLD_LEAGUES[k];const out=[];if(!L)return out;for(const c of L.clubs){const e=eu.find(x=>x.name===c[0]);if(e)out.push(e);else if(RAW_EURO[c[0]]&&RAW_EURO[c[0]].length>=14)out.push({key:'w:'+k+':'+c[0],name:c[0],country:c[6]||L.country,c1:c[2],c2:c[3],str:c[4],def:[c[0],c[6]||L.country,c[1],'',c[2],c[3],c[4]]})}
    if(withCountry)for(const e of eu)if(e.country===withCountry&&!out.includes(e))out.push(e);return out.sort((a,b)=>b.str-a.str)};
  const alef=lg=>(typeof RAW_ALEF!=='undefined'?RAW_ALEF:[]).filter(a=>a[4]===lg).map(a=>({key:'a:'+a[0],name:a[0],country:'ישראל',city:a[1],c1:a[2],c2:a[3],str:52}));
  const C=[{id:'il',name:'ישראל',leagues:[{id:'il1',name:'ליגת העל',tier:1,clubs:il},{id:'il2',name:'ליגה לאומית',tier:2,clubs:LEUMIT16.map(d=>({key:'l:'+d.id,name:d.name,country:'ישראל',c1:d.c1,c2:d.c2,str:d.str||55}))},{id:'il3n',name:'ליגה א׳ צפון',tier:3,clubs:alef('alef_north')},{id:'il3s',name:'ליגה א׳ דרום',tier:3,clubs:alef('alef_south')}]},
    {id:'en',name:'אנגליה',leagues:[{id:'en1',name:'פרמייר ליג',tier:1,clubs:W('epl','אנגליה')},{id:'en2',name:'צ׳מפיונשיפ',tier:2,clubs:W('champ')}]},
    {id:'es',name:'ספרד',leagues:[{id:'es1',name:'לה ליגה',tier:1,clubs:W('laliga','ספרד')},{id:'es2',name:'לה ליגה 2',tier:2,clubs:W('segunda')}]},
    {id:'it',name:'איטליה',leagues:[{id:'it1',name:'סרייה א׳',tier:1,clubs:W('seriea','איטליה')}]},
    {id:'de',name:'גרמניה',leagues:[{id:'de1',name:'בונדסליגה',tier:1,clubs:W('bundes','גרמניה')}]},
    {id:'fr',name:'צרפת',leagues:[{id:'fr1',name:'ליג 1',tier:1,clubs:W('ligue1','צרפת')}]},
    {id:'nl',name:'הולנד',leagues:[{id:'nl1',name:'ארדיוויזי',tier:1,clubs:W('eredivisie','הולנד')}]},
    {id:'pt',name:'פורטוגל',leagues:[{id:'pt1',name:'ליגת פורטוגל',tier:1,clubs:W('portugal','פורטוגל')}]},
    {id:'be',name:'בלגיה',leagues:[{id:'be1',name:'ליגת בלגיה',tier:1,clubs:W('belgium','בלגיה')}]}];
  for(const c of C)c.leagues=c.leagues.filter(l=>l.clubs.length>=6);Bcat.c=C.filter(c=>c.leagues.length);
  /* the Champions League as a league of its own: the strongest clubs of the continent, at most four of one country. It stands
     last, so a club is always found in its own country's league first (BcatFind) */
  const per={},best=[];for(const {x,c} of Bcat.c.flatMap(c=>c.leagues.filter(l=>l.tier===1).flatMap(l=>l.clubs.map(x=>({x,c})))).sort((a,b)=>b.x.str-a.x.str)){if(best.length>=BCL_N)break;if(best.includes(x)||(per[c.id]||0)>=4)continue;per[c.id]=(per[c.id]||0)+1;best.push(x)}
  if(best.length>=8)Bcat.c.push({id:'cl',name:'אירופה',cup:true,leagues:[{id:'cl1',name:'ליגת האלופות',tier:0,cup:true,clubs:best}]});return Bcat.c}
const BCL_N=16;
const LSTR={mta:70,hta:69,mhf:69,hbs:70,bje:67,hhf:64,hje:63,mnt:64,mpt:61,bsk:61,hpt:61,hrg:59,iks:59,itb:59};
function BcatLeague(id){for(const c of Bcat())for(const l of c.leagues)if(l.id===id)return l;return null}
function BcatFind(key){for(const c of Bcat())for(const l of c.leagues){const x=l.clubs.find(x=>x.key===key);if(x)return {x,l,country:c}}return null}
function BclubByKey(key){return G.clubs.find(c=>c.bkey===key)||null}
/* what every club of a beginner career needs, whatever built it */
function BprepClub(c,key){if(key)c.bkey=key;c.div='top';c.pseudo=false;c.country=c.country||'ישראל';if(!c.realSquad)c.players.forEach(p=>p.real=false);c.youth=[];c.academy=0;c.sponsor=null;c.formation='4-3-3';c.ticket=80;if(c.fans==null)c.fans=50;c.baseDemand=Math.round(c.cap*(.48+c.fans/200));c.P=c.W=c.D=c.L=c.GF=c.GA=c.pts=0;autoLineupFor(c);return c}
function BaddClub(x){let c=BclubByKey(x.key);if(c)return c;
  if(x.key.startsWith('l:')){const d=LEUMIT16.find(d=>d.id===x.key.slice(2));if(!d)return null;c=buildLeumitClub(d)}
  else if(x.key.startsWith('a:'))c=buildLeumitClub({id:'ba'+(uid++),name:x.name,short:x.name.replace(/^(הפועל|מכבי|מ\.ס\.|מ\.כ\.|עירוני|בית"ר) /,''),city:x.city,stadium:'אצטדיון '+x.city,cap:3500,c1:x.c1,c2:x.c2,str:52});
  else if(x.def){c=clubFromDef(x.def,'b');delete G.pseudo[c.id];c.squadValue=c.players.reduce((s,p)=>s+Bvalue(p),0);c.money=Math.round(Math.max(8e6,c.squadValue*.3))}else return null;
  c.country=x.country;BprepClub(c,x.key);G.clubs.push(c);return c}
function BensureLeague(l){return l.clubs.map(x=>BaddClub(x)).filter(Boolean).map(c=>c.id)}
function BensureKeys(){for(const c of G.clubs){if(c.bkey)continue;if(META[c.id])c.bkey=c.id;else{const i=EURO_CLUBS.findIndex(d=>d[0]===c.name);if(i>=0)c.bkey='eu'+i}}const b=Bstate();if(!b.leagueId){const f=BcatFind(me().bkey);if(f&&f.l.clubs.every(x=>BclubByKey(x.key)&&b.league.includes(BclubByKey(x.key).id))&&b.league.length===f.l.clubs.length)b.leagueId=f.l.id}}
function BleagueName(){const l=BcatLeague(Bstate().leagueId);return l?l.name:'ליגת האימון'}
function Bplace(c=me()){return Bstandings().indexOf(c)+1}
/* ---- contract and board ---- */
function BcontractFor(x,l){const n=l.clubs.length,above=l.clubs.filter(y=>y.str>x.str).length,ties=l.clubs.filter(y=>y.str===x.str).length,rank=Math.round(above+(ties+1)/2);   /* clubs of equal strength share the middle of their group */
  return {years:2,wage:Math.round((9000+Math.pow(1.085,x.str-50)*7000)/500)*500,goal:clamp(rank+2,1,n-1),rank,n}}
function BgoalText(k){return k.goal<=1?'לזכות באליפות':`לסיים במקום <bdi>${k.goal}</bdi> או גבוה ממנו`}
function BsignCoach(key,leagueId,opt){const f=BcatFind(key),l=BcatLeague(leagueId)||f.l,x=l.clubs.find(y=>y.key===key),b=Bstate();b.contract=Object.assign(BcontractFor(x,l),{since:b.season});b.board=55;b.offer=null;b.offerAt=null;b.out=null;b.verdict=null;b.jobs=b.jobs||[];b.jobs.push({season:b.season,club:x.name,league:l.name});if(opt&&opt.name!=null){b.coach=opt.name;if(G.manager)G.manager.name=opt.name}}
function BboardWord(v){return v>=75?'מרוצה מאוד':v>=55?'מרוצה':v>=35?'מודאגת':v>=20?'לוחצת':'על סף החלטה'}
/* after the coach's match: the result against what was expected of it, then the table against the goal */
function BboardAfter(M){const b=Bstate();if(!b.contract||b.out)return;const c=me(),home=M.h===c.id,gf=home?M.gh:M.ga,ga=home?M.ga:M.gh,opp=club(home?M.a:M.h),gap=strength(c)-strength(opp);
  let d=gf>ga?(gap<-4?6:4):gf===ga?(gap<-4?2:gap>4?-1:1):(gap<-4?-2:gap>4?-7:-5);if(b.round>=5){const pos=Bplace(c);d+=pos<=b.contract.goal?1:-(pos-b.contract.goal>3?2:1)}b.board=clamp((b.board==null?55:b.board)+d,0,100)}
/* ---- the job market ---- */
function BjobPool(lo,hi,sameLeague){const b=Bstate(),mine=me().bkey,out=[];for(const c of Bcat())for(const l of c.leagues){if(sameLeague?l.id!==b.leagueId:l.cup)continue;for(const x of l.clubs)if(x.key!==mine&&x.str>=lo&&x.str<=hi)out.push({key:x.key,league:l.id})}return out}
function BjobOffer(o){const f=BcatFind(o.key),l=BcatLeague(o.league),x=l.clubs.find(y=>y.key===o.key);return Object.assign({key:o.key,league:o.league,name:x.name,leagueName:l.name,c1:x.c1,c2:x.c2},BcontractFor(x,l))}
function BjobOffers(lo,hi,n,sameLeague){const pool=shuffle(BjobPool(lo,hi,sameLeague)),seen=new Set(),out=[];for(const o of pool){if(out.length>=n)break;if(seen.has(o.key))continue;seen.add(o.key);out.push(BjobOffer(o))}return out}
function BmyStr(){const f=BcatFind(me().bkey);return f?f.x.str:Math.round(strength(me()))}
/* out of work: clubs a step down always answer, so a career never ends on this screen */
function Bleave(why){const b=Bstate(),s=BmyStr();Breturnloans();let offers=BjobOffers(s-(why==='fired'?16:12),s-(why==='fired'?3:-1),3);if(offers.length<2)offers=BjobOffers(0,s+2,3);if(offers.length<2)offers=BjobOffers(0,200,3);
  b.out={why,from:me().name,offers};b.offer=null;b.live=null;if(b.jobs&&b.jobs.length)b.jobs[b.jobs.length-1].end=why;Bwrite();Brender()}
function Breturnloans(){const b=Bstate();for(const l of b.loans||[]){const p=me().players.find(p=>p.id===l.pid),to=club(l.club);if(p&&to){me().players=me().players.filter(x=>x.id!==p.id);to.players.push(p)}}b.loans=[]}
/* take a job. In the league being played he joins its table as it stands; anywhere else a new season starts there. */
function BtakeJob(o){const b=Bstate(),l=BcatLeague(o.league),same=!b.out&&l.id===b.leagueId&&b.round<b.schedule.length;Breturnloans();b.build=null;const ids=BensureLeague(l),c=BclubByKey(o.key);if(!c)return;
  G.me=c.id;c.sponsor=null;BensureXI(c);c.money=Math.max(c.money,Math.round(Bsum()*.7));
  if(!same){if(b.out||b.round>0){b.season++;G.season=b.season}b.league=ids;b.leagueId=l.id;Bseason()}
  BsignCoach(o.key,l.id);b.opening=c.money;b.sponsorOffers=pickSponsorBrands(c,3).map(x=>({id:x.id,annual:Math.round(Math.max(Bsum()*.4,300000)),years:1}));Btab='home';Bnotice='חתמת ב'+c.name;Bwrite();Brender()}
/* after every round: dismissal, and now and then an offer from a bigger club of the same league */
function BcareerRound(){const b=Bstate();if(!b.contract||b.out)return null;const n=b.schedule.length,left=n-b.round;
  if(b.offer&&b.round>=b.offer.until)b.offer=null;
  if(b.round>=Math.max(8,Math.round(n*.35))&&left>=2&&b.board<=12)return 'fired';
  if(!b.offer&&left>=4&&b.round>=5&&b.board>=68&&Bplace()<=b.contract.goal&&(b.round===Math.round(n/2)||Math.random()<.14)&&b.offerAt!==b.season+':'+Math.floor(b.round/6)){const s=BmyStr(),o=BjobOffers(s+1,s+12,1,true)[0];if(o){b.offer=Object.assign(o,{until:b.round+2});b.offerAt=b.season+':'+Math.floor(b.round/6)}}
  return null}
/* the end of a season: did he meet the goal, does the contract go on, who calls */
function BseasonVerdict(){const b=Bstate(),k=b.contract;if(!k)return {stay:true,offers:[],text:''};const pos=Bplace(),met=pos<=k.goal,s=BmyStr();if(b.verdict&&b.verdict.season===b.season)return b.verdict;
  const yearsLeft=k.years-(b.season-k.since+1);let stay=true,text;
  if(!met&&(pos-k.goal>=3||b.board<30)){stay=false;text=`סיימת במקום <bdi>${pos}</bdi>, והיעד היה ${BgoalText(k)}. ההנהלה החליטה להיפרד.`}
  else if(yearsLeft<=0&&b.board<40){stay=false;text=`החוזה הסתיים וההנהלה בחרה לא לחדש אותו.`}
  else text=met?`עמדת ביעד: מקום <bdi>${pos}</bdi>. ${yearsLeft<=0?'ההנהלה מציעה חוזה חדש.':'החוזה ממשיך.'}`:`סיימת במקום <bdi>${pos}</bdi>, מעט מתחת ליעד. ההנהלה נותנת עונה נוספת.`;
  const up=met?clamp(Math.round((k.goal-pos)*1.5)+Math.round((b.board-55)/8),0,12):0;const offers=stay?BjobOffers(s-4,s+2+up,2):[];
  b.verdict={season:b.season,stay,text,offers,met,pos,renew:stay&&yearsLeft<=0};return b.verdict}
function BstayOn(){const b=Bstate(),v=b.verdict;if(v&&v.renew){const f=BcatFind(me().bkey),l=BcatLeague(b.leagueId)||(f&&f.l);if(f&&l)b.contract=Object.assign(BcontractFor(f.x,l),{since:b.season+1})}b.board=clamp(Math.round(((b.board==null?55:b.board)+55)/2),30,80);b.verdict=null}
/* ---- screens ---- */
function BofferHTML(o,attr,cta){return `<article class="boffer">${kitSVG(o,'lg')}<div><strong>${esc(o.name)}</strong><small>${esc(o.leagueName)} · חוזה ל־<bdi>${o.years}</bdi> עונות · ${Bmoney(o.wage)} לחודש</small><small>היעד: ${BgoalText(o)}</small></div>${Bbutton(cta||'לחתום',`${attr}="${esc(o.key)}"`,'secondary')}</article>`}
function BcareerPanel(){const b=Bstate(),k=b.contract;if(!k)return '';const until=k.since+k.years-1,v=b.board==null?55:b.board;
  return `<section class="bpanel bcareer"><div class="bcareer-head"><div><span class="beyebrow">המאמן</span><h2>${esc(b.coach||'המאמן')}</h2><p>${esc(BleagueName())} · חוזה עד סוף עונה <bdi>${until}</bdi> · היעד: ${BgoalText(k)}</p></div><button type="button" class="blink" data-action="resign">להתפטר</button></div>
  <div class="bboard" role="img" aria-label="אמון ההנהלה ${v} מתוך 100"><span>אמון ההנהלה</span><div class="bboard-bar"><i style="width:${v}%" class="${v>=55?'good':v>=30?'mid':'low'}"></i></div><strong>${BboardWord(v)}</strong></div>
  ${b.offer?`<div class="boffers"><h3>הצעה על השולחן (עד מחזור <bdi>${b.offer.until}</bdi>)</h3>${BofferHTML(b.offer,'data-bjob','לעבור עכשיו')}<button type="button" class="blink" data-action="decline">לדחות את ההצעה</button></div>`:''}</section>`}
function BoutHTML(){const o=Bstate().out;return `<div class="bapp"><header class="btop"><a class="bbrand" href="beginner.html">GOALASSO<span>START</span></a><span class="bpill">מצב מתחילים</span></header><section class="bpanel bout">${Bheader(o.why==='fired'?'פיטורים':'התפטרות',o.why==='fired'?`${esc(o.from)} נפרדה ממך`:`עזבת את ${esc(o.from)}`,o.why==='fired'?'התוצאות לא הספיקו להנהלה. מאמנים טובים חוזרים מזה: בחר את התחנה הבאה.':'מי שמחפש אתגר חדש מוצא אותו. אלה המועדונים שרוצים אותך עכשיו.')}<div class="boffers">${o.offers.map(x=>BofferHTML(x,'data-bjob')).join('')}</div><p class="bmuted">עונה חדשה תתחיל במועדון שתבחר. הסגל, הכסף והטבלה הם של המועדון החדש.</p></section></div>`}
/* the opening: name, league, club; the contract is signed in a dialog */
/* flags, drawn (emoji flags are missing on some systems and England has none of its own) */
function Bflag(id){const R=(x,y,w,h,f)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${f}"/>`,V=(a,b,c)=>R(0,0,12,24,a)+R(12,0,12,24,b)+R(24,0,12,24,c),H=(a,b,c)=>R(0,0,36,8,a)+R(0,8,36,8,b)+R(0,16,36,8,c);
  const F={il:R(0,0,36,24,'#fff')+R(0,3,36,3.4,'#0038b8')+R(0,17.6,36,3.4,'#0038b8')+'<path d="M18 7.6l3.5 6h-7zM18 16.4l-3.5-6h7z" fill="none" stroke="#0038b8" stroke-width="1.1"/>',
    en:R(0,0,36,24,'#fff')+R(15,0,6,24,'#ce1124')+R(0,9,36,6,'#ce1124'),es:R(0,0,36,24,'#aa151b')+R(0,6,36,12,'#f1bf00'),it:V('#009246','#fff','#ce2b37'),de:H('#111','#dd0000','#ffce00'),fr:V('#0055a4','#fff','#ef4135'),
    nl:H('#ae1c28','#fff','#21468b'),pt:R(0,0,14.4,24,'#046a38')+R(14.4,0,21.6,24,'#da291c')+'<circle cx="14.4" cy="12" r="4.4" fill="#ffe900" stroke="#fff" stroke-width=".6"/>',be:V('#111','#fae042','#ed2939')};
  return `<svg class="bflag" viewBox="0 0 36 24" aria-hidden="true">${F[id]||R(0,0,36,24,'#33475b')}</svg>`}
/* the opening: the name (also asked on the title screen), then the league and the club in front of the stadium */
function BstartHTML(){const s=Bstart,cat=Bcat();const back=(to,t)=>`<button type="button" class="blink" data-bstep="${to}">${t||'חזרה'}</button>`;
  if(s.step==='league'){const q=(s.q||'').trim();const hits=q.length>=2?cat.filter(c=>!c.cup).flatMap(c=>c.leagues.flatMap(l=>l.clubs.filter(x=>x.name.includes(q)).map(x=>({x,l})))).slice(0,12):[];
    return `<section class="bpick" id="bstart"><h1>${esc(s.name)}, איפה תאמן?</h1><p class="bpick-sub">בחר מדינה וליגה. את המועדון תבחר מיד אחר כך.</p>
    <div class="bcountries">${cat.filter(c=>!c.cup).map(c=>`<div class="bcountry${s.country===c.id?' open':''}"><button type="button" data-bcountry="${c.id}" aria-expanded="${s.country===c.id}">${Bflag(c.id)}<strong>${esc(c.name)}</strong><small>${c.leagues.length>1?`<bdi>${c.leagues.length}</bdi> ליגות`:esc(c.leagues[0].name)}</small></button>${s.country===c.id&&c.leagues.length>1?`<div class="bleagues">${c.leagues.map(l=>`<button type="button" data-bleague="${l.id}"><strong>${esc(l.name)}</strong><small><bdi>${l.clubs.length}</bdi> מועדונים</small></button>`).join('')}</div>`:''}</div>`).join('')}</div>
    <div class="bmodes">${BcatLeague('cl1')?`<button type="button" class="bmode" data-bleague="cl1"><span class="bmode-ic" aria-hidden="true">★</span><strong>ליגת האלופות</strong><small><bdi>${BcatLeague('cl1').clubs.length}</bdi> המועדונים החזקים באירופה, כולם נגד כולם</small></button>`:''}<button type="button" class="bmode" data-room-open><span class="bmode-ic" aria-hidden="true">⇄</span><strong>משחק רשת</strong><small>משחק ידידות מול חבר, עם קוד הזמנה</small></button></div>
    <div class="bfilters"><label>או חפש מועדון בשם<input id="bclubsearch" value="${esc(s.q||'')}" placeholder="למשל ליברפול או מכבי חיפה" autocomplete="off"></label></div>${hits.length?`<div class="bclubgrid">${hits.map(({x,l})=>`<button class="bclub" data-bpick="${esc(x.key)}" data-bpl="${l.id}">${kitSVG(x,'lg')}<strong>${esc(x.name)}</strong><span>${esc(l.name)}</span></button>`).join('')}</div>`:q.length>=2?'<p class="bmuted">לא נמצא מועדון בשם הזה.</p>':''}${back('name','שינוי שם')}</section>`}
  if(s.step==='club'){const l=BcatLeague(s.league),c=cat.find(c=>c.leagues.includes(l));return `<section class="bpick" id="bstart"><h1>${l.cup?'<span class="bstar" aria-hidden="true">★</span>':Bflag(c?c.id:'')} ${esc(l.name)}</h1><p class="bpick-sub">${l.cup?'הגדולים של אירופה בליגה אחת, בית וחוץ. כאן אין יריבה קלה. ':''}איזה מועדון תוביל? מועדון חזק נותן סגל טוב יותר, וגם יעד קשה יותר בחוזה.</p><div class="bclubgrid">${l.clubs.map(x=>`<button class="bclub" data-bpick="${esc(x.key)}" data-bpl="${l.id}">${kitSVG(x,'lg')}<strong>${esc(x.name)}</strong><span>${l.cup?esc(x.country||'')+' · ':''}חוזק <bdi>${Math.round(x.str)}</bdi></span></button>`).join('')}</div>${back('league','חזרה לליגות')}</section>`}
  return `<section class="bpanel bstart" id="bstart"><h2>איך קוראים לך, מאמן?</h2><form data-bnameform><label class="bfield">השם שיופיע על החוזה<input id="bcoach" maxlength="24" autocomplete="name" value="${esc(s.name)}" placeholder="למשל אבי לוי"></label><p class="bstart-err" role="alert">${esc(s.err||'')}</p>${Bbutton('ממשיכים לבחירת ליגה','type="submit"')}</form></section>`}
function BcontractDialog(key,leagueId){const f=BcatFind(key),l=BcatLeague(leagueId)||f.l,x=l.clubs.find(y=>y.key===key),k=BcontractFor(x,l);Bstart.club=key;Bstart.league=l.id;
  Bdialog(`<div class="bcontract"><span class="beyebrow">חוזה מאמן</span><h2>${kitSVG(x,'lg')} ${esc(x.name)}</h2><dl><dt>המאמן</dt><dd>${esc(Bstart.name)}</dd><dt>הליגה</dt><dd>${esc(l.name)}</dd><dt>תקופה</dt><dd><bdi>${k.years}</bdi> עונות</dd><dt>שכר</dt><dd>${Bmoney(k.wage)} לחודש</dd><dt>היעד של ההנהלה</dt><dd>${BgoalText(k)}</dd></dl><p class="blearn">ההנהלה עוקבת אחרי התוצאות. מי שעומד ביעד מקבל הצעות ממועדונים גדולים יותר; מי שרחוק ממנו עלול להיות מפוטר.</p>${Bbutton('חותם על החוזה','data-bsign')}<button type="button" class="blink" data-bclose>בוחר מועדון אחר</button></div>`)}
/* the title screen's button: a new coach must have written a name; true = the title screen may close */
function BsplashGo(){if(G?.beginner)return true;const el=document.getElementById('spName');if(!el)return true;const v=el.value.trim();if(v.length<2){el.setAttribute('aria-invalid','true');const er=document.getElementById('spErr');if(er)er.textContent='כתוב שם של שתי אותיות לפחות.';el.focus();return false}
  Bstart.name=v;Bstart.err='';Bstart.step='league';Brender();setTimeout(()=>document.getElementById('bstart')?.scrollIntoView?.({block:'start'}),480);return true}
/* clicks of the opening steps (no career yet); true = handled */
function BstartClick(el){const d=el.dataset;if(d.bstep){Bstart.step=d.bstep;Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bcountry){const c=Bcat().find(x=>x.id===d.bcountry);if(!c)return true;if(c.leagues.length===1){Bstart.country=c.id;Bstart.league=c.leagues[0].id;Bstart.step='club'}else Bstart.country=Bstart.country===c.id?null:c.id;Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bleague){Bstart.league=d.bleague;Bstart.step='club';Brender();$('bstart')?.scrollIntoView?.({block:'start'});return true}
  if(d.bpick){if(G?.beginner)return true;BcontractDialog(d.bpick,d.bpl);return true}
  if(el.hasAttribute('data-bsign')){if(G?.beginner||!Bstart.club)return true;el.closest('dialog')?.remove();const s=Bstart;Bcreate(s.club,{name:s.name,league:s.league});Bstart={step:'name',name:'',country:null,league:null,club:null,q:'',err:''};window.scrollTo?.(0,0);return true}
  return false}
document.addEventListener('submit',e=>{if(!e.target.matches||!e.target.matches('[data-bnameform]'))return;e.preventDefault();const v=(document.getElementById('bcoach')?.value||'').trim();if(v.length<2){Bstart.err='כתוב שם של שתי אותיות לפחות.';Brender();document.getElementById('bcoach')?.focus();return}Bstart.name=v;Bstart.err='';Bstart.step='league';Brender();$('bstart')?.scrollIntoView?.({block:'start'})});
Bload();if(G?.beginner?.live)G.beginner.live.paused=true;Brender();try{updateWatch()}catch(e){}try{pcupFromLink()}catch(e){}window.BEGINNER={get state(){return G},create:Bcreate,render:Brender,play:Bplay,save:Bwrite};

if(!window.__ilmNoSplash&&!Rooms.arrival())showSplash();
Rooms.boot();
